#include "tigersheets/workbook_tools.hpp"
#include "tigersheets/calculation.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* text){if(!okay)throw std::runtime_error(text);}
int main(){try{Json book={{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Data"},{"cells",Json::array({{{"row",1},{"col",1},{"input","Region"}},{{"row",1},{"col",2},{"input","Revenue"}},{{"row",2},{"col",1},{"input","East"}},{{"row",2},{"col",2},{"input","12"}},{{"row",3},{"col",1},{"input","West"}},{{"row",3},{"col",2},{"input","18"}}})}},{{"id","r"},{"name","Report"},{"cells",Json::array()}}})}};
 WorkbookSession session(book);WorkbookTools tools(session,Json::object());tools.calculate=[](const Json& snapshot){return CalculationEngine().calculate(snapshot);};
 Json definition={{"id","p1"},{"name","RevenueReport"},{"source",{{"sheet","s"},{"row1",1},{"col1",1},{"row2",3},{"col2",2}}},{"rows",Json::array({{{"field","Region"}}})},{"values",Json::array({{{"field","Revenue"},{"aggregate","sum"},{"name","Revenue"}}})},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}};
 auto reply=tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","create_pivot"},{"definition",definition}}})}});
 require(reply.value("status",std::string())=="preview","Codex can propose a genuine pivot through typed operations");require(!session.snapshot().contains("pivots"),"report authoring is isolated until acceptance");
 auto read=tools.invoke("workbook_v1_report",{{"id","p1"},{"rowLimit",10}});require(read.at("definition").at("id")=="p1"&&!read.at("definition").contains("cache"),"bounded report read omits the complete source cache");require(read.at("data").size()==2,"report reads see the pending generation");
 reply=tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({{{"type","create_pivot_chart"},{"pivotId","p1"},{"id","pc1"},{"chartType","line"}}})}});require(reply.value("status",std::string())=="preview","PivotChart composes with the existing proposal");require(session.accept(),"report proposal accepts once");require(session.snapshot()["charts"][0]["pivotId"]=="p1","accepted chart retains pivot linkage");require(session.undo()&&!session.snapshot().contains("pivots"),"one undo removes table and chart proposal together");
 require(session.redo(),"restore report for field editing");const auto revision=session.snapshotView().at("revision");
 const Json filter={{"field","Region"},{"all",false},{"items",Json::array({{{"type","string"},{"value","East"}}})}};
 const Json update={{"type","update_pivot"},{"id","p1"},{"changes",{{"filters",Json::array({filter})}}}};
 reply=tools.invoke("workbook_v1_preview",{{"revision",revision},{"operations",Json::array({update})}});
 require(reply.value("status",std::string())=="preview","typed update regenerates a pivot and linked chart in the proposal");read=tools.invoke("workbook_v1_report",{{"id","p1"}});require(read.at("data").size()==1&&read.at("data")[0][0]["value"]==12,"filter changes update the proposed totals");require(session.accept(),"accept field edit");
 const auto refreshRevision=session.snapshotView().at("revision");
 reply=tools.invoke("workbook_v1_preview",{{"revision",refreshRevision},{"operations",Json::array({{{"type","set_cell"},{"sheet","s"},{"row",2},{"col",2},{"input","22"}},{{"type","refresh_pivot"},{"id","p1"}}})}});
 require(reply.value("status",std::string())=="preview","typed refresh composes with source edits in one proposal");read=tools.invoke("workbook_v1_report",{{"id","p1"}});require(read.at("data")[0][0]["value"]==22,"refresh reads the changed proposed source");require(session.accept(),"accept source edit and refresh together");
 const auto moveRevision=session.snapshotView().at("revision");
 reply=tools.invoke("workbook_v1_preview",{{"revision",moveRevision},{"operations",Json::array({{{"type","move_pivot"},{"id","p1"},{"output",{{"sheet","r"},{"row1",10},{"col1",5}}}}})}});require(reply.value("status",std::string())=="preview","typed move relocates an existing report in an isolated proposal");
 read=tools.invoke("workbook_v1_report",{{"id","p1"}});require(read.at("definition")["output"]["row1"]==10&&read.at("data")[0][0]["value"]==22,"move retains aggregate values at the new output");require(session.accept(),"accept report relocation");
 const auto unchangedRevision=session.snapshotView().at("revision");reply=tools.invoke("workbook_v1_preview",{{"revision",unchangedRevision},{"operations",Json::array({{{"type","refresh_pivot"},{"id","p1"}}})}});require(reply.value("status",std::string())=="unchanged"&&!session.hasPreview()&&session.snapshotView().at("revision")==unchangedRevision,"unchanged refresh creates no preview or history revision");
 const auto chartRevision=session.snapshotView().at("revision");reply=tools.invoke("workbook_v1_preview",{{"revision",chartRevision},{"operations",Json::array({{{"type","update_pivot_chart"},{"id","pc1"},{"changes",{{"chartType","bar"},{"title","Regional revenue"},{"anchor",{{"row",15},{"col",7},{"width",640},{"height",320}}}}}}})}});require(reply.value("status",std::string())=="preview","typed PivotChart update preserves native linkage in a proposal");
 auto charts=tools.invoke("workbook_v1_read",{{"sheet","r"},{"metadata",Json::array({"charts"})}}).at("charts");require(charts[0]["pivotId"]=="p1"&&charts[0]["type"]=="bar"&&charts[0]["title"]=="Regional revenue"&&charts[0]["anchor"]["row"]==15,"PivotChart update changes presentation without detaching the report");require(session.accept(),"accept PivotChart update");
 const auto chartDeleteRevision=session.snapshotView().at("revision");reply=tools.invoke("workbook_v1_preview",{{"revision",chartDeleteRevision},{"operations",Json::array({{{"type","delete_pivot_chart"},{"id","pc1"}}})}});require(reply.value("status",std::string())=="preview","typed PivotChart deletion is previewed");require(session.accept()&&session.snapshotView()["charts"].empty()&&session.snapshotView()["pivots"].size()==1,"chart deletion preserves its source pivot");
 const auto linkedDeleteRevision=session.snapshotView().at("revision");reply=tools.invoke("workbook_v1_preview",{{"revision",linkedDeleteRevision},{"operations",Json::array({{{"type","create_pivot_chart"},{"pivotId","p1"},{"id","pc2"},{"chartType","column"}}})}});require(reply.value("status",std::string())=="preview"&&session.accept(),"prepare an accepted linked chart for report deletion");
 const auto deleteRevision=session.snapshotView().at("revision");reply=tools.invoke("workbook_v1_preview",{{"revision",deleteRevision},{"operations",Json::array({{{"type","delete_pivot"},{"id","p1"}}})}});require(reply.value("status",std::string())=="preview","typed report deletion remains isolated in a proposal");require(session.snapshotView()["pivots"].size()==1&&tools.invoke("workbook_v1_report",{{"id","p1"}}).contains("error"),"deleted report disappears only from pending reads");require(session.accept()&&session.snapshotView()["pivots"].empty()&&session.snapshotView()["charts"].empty(),"deleting a report removes generated output and linked charts together");require(session.undo()&&session.snapshotView()["pivots"].size()==1&&session.snapshotView()["charts"].size()==1,"one undo restores a deleted report and its linked chart");
 auto listed=tools.invoke("workbook_v1_reports",{{"limit",1}});require(!listed.contains("error")&&listed.at("reports").size()==1&&listed.at("reports")[0]["id"]=="p1"&&!listed.at("reports")[0].contains("cache"),"bounded report list discovers native reports without source caches");
 auto memberBook=session.snapshot();auto& fieldItems=memberBook["pivots"][0]["cache"]["fields"][0]["items"];for(int i=0;i<300;++i)fieldItems.push_back({{"type","string"},{"value","Case"+std::to_string(i)}});fieldItems.push_back({{"type","number"},{"value",123}});fieldItems.push_back({{"type","string"},{"value","123"}});fieldItems.push_back({{"type","blank"},{"value",nullptr}});
 memberBook["pivots"][0]["filters"][0]["items"].push_back({{"type","string"},{"value","Gone"}});memberBook["pivots"][0]["filters"][0]["missingItems"]=Json::array({{{"type","string"},{"value","Gone"}}});WorkbookSession memberSession(memberBook);WorkbookTools memberTools(memberSession,Json::object());
 auto members=memberTools.invoke("workbook_v1_pivot_members",{{"id","p1"},{"field","Region"},{"query","Case299"}});require(!members.contains("error")&&members.at("items").size()==1&&members.at("items")[0]["item"]["value"]=="Case299","member search finds values beyond its first bounded result window");
 members=memberTools.invoke("workbook_v1_pivot_members",{{"id","p1"},{"field","Region"},{"query","Case"},{"offset",199},{"limit",2}});require(members.at("items").size()==2&&members.at("items")[0]["item"]["value"]=="Case199"&&members.at("matchCount")==300&&members.at("truncated")==true,"typed member search supports bounded pagination");
 members=memberTools.invoke("workbook_v1_pivot_members",{{"id","p1"},{"field","Region"},{"query","123"}});bool numericMember=false,textMember=false;for(const auto& entry:members.at("items")){const auto& item=entry.at("item");numericMember|=item.at("type")=="number"&&item.at("value")==123;textMember|=item.at("type")=="string"&&item.at("value")=="123";}require(members.at("items").size()==3&&numericMember&&textMember,"member reads preserve number versus text identities alongside substring matches");
 members=memberTools.invoke("workbook_v1_pivot_members",{{"id","p1"},{"field","Region"},{"query","Gone"}});require(members.at("items").size()==1&&members.at("items")[0]["missing"]==true&&members.at("items")[0]["selected"]==true,"missing selected members remain discoverable");
 require(memberTools.invoke("workbook_v1_pivot_members",{{"id","p1"},{"field","Region"},{"limit",201}}).contains("error"),"member read bounds are enforced");
 std::cout<<"reporting tools tests passed\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
